export function slugify(value: string): string {
  const lower = value.toLowerCase();
  const withHyphens = lower.replace(/[^\w\s-]/g, '-');
  const collapsed = withHyphens.replace(/[-\s]+/g, '-').trim();
  return collapsed.replace(/^-+|-+$/g, '');
}

